# L'executa tests/integracio.py, que hi posa les funcions comunes (G, P, ok, n, db…).

ok(n('select count(*) from tipus_obres')==13 and n("select nom from tipus_obres order by ordre")==('Pasdoble' if L=='ca' else 'Pasodoble'), 'tipus d obra inicials')
ok(n('select count(*) from obres')==13, 'obres d exemple')
h=G('r=repertori'); ok(not err(h) and 'Paquito el chocolatero' in h and 'ARX-0013' in h, 'pantalla repertori')
ok(h.index('Amarguras')<h.index('Amparito Roca')<h.index('Chimo'), 'ordre per títol')
h=G('r=repertori&q=serrano'); ok('El fallero' in h and 'Amparito' not in h, 'cerca per compositor')
h=G('r=repertori&q=arx-0011'); ok('Luis Alonso' in h and 'Chimo' not in h, 'cerca per número')
h=G('r=repertori&q=carpeta+12'); ok(('Pirates' in h or 'Piratas' in h) and 'Chimo' not in h, 'cerca per ubicació')
tp=n("select id from tipus_obres where nom like 'Marx% mora' or nom like 'Marc% mora'")
h=G(f'r=repertori&tipus={tp}'); ok('Chimo' in h and 'Ragón Falez' in h and 'Amparito' not in h, 'filtre per tipus')
coral=n("select id from agrupacions where nom='Coral'"); h=G(f'r=repertori&agrupacio={coral}'); ok(('Himne' in h or 'Himno' in h) and 'Chimo' not in h, 'filtre per agrupació')
h=G('r=repertori&agrupacio=cap'); ok('ARX-0013' in h and 'ARX-0001' not in h, 'obres sense agrupació')
h=G('r=repertori&estat=incomplet'); ok('El fallero' in h and 'Chimo' not in h, 'filtre per estat')
h=G('r=repertori&dig=1'); ok('Paquito' in h and 'El fallero' not in h, 'filtre digitalitzades')
h=G('r=repertori&ordre=numero'); ok(h.index('ARX-0002')<h.index('ARX-0010')<h.index('ARX-0013'), 'ordre per número')
h=G('r=repertori&ordre=compositor'); ok(h.index('Franz von Supp')<h.index('Gustavo Pascual')<h.index('Salvador Giner'), 'ordre per compositor')
csvt=G('r=repertori&csv=1&estat=complet', raw=True).decode('utf-8-sig'); files=list(csv.reader(io.StringIO(csvt), delimiter=';'))
ok(len(files)==11 and files[1][0].startswith('ARX'), 'CSV filtrat (%d files)'%len(files))
obra=n("select id from obres where numero_arxiu='ARX-0003'")
h=G(f'r=fitxa&e=obres&id={obra}'); ok(not err(h) and 'avis atencio' in h and 'Banda' in h, 'fitxa amb avís d incompleta i agrupacions')
h=G('r=edita&e=obres'); ok('value="ARX-0014"' in h and 'name="agrupacions[]"' in h, 'obra nova proposa ARX-0014 i caselles d agrupacions')
banda=n("select id from agrupacions where nom='Banda'"); juvenil=n("select id from agrupacions where nom='Banda juvenil'")
base=dict(titol='Obra nova', tipus_id=tp, compositor='Prova', arranjador='', numero_arxiu='ARX-0014', ubicacio='Armari C', material='', estat='complet', digitalitzada='0', observacions='')
h=P('r=edita&e=obres', dict(base, **{'agrupacions[]':['', str(banda), str(juvenil)]}))
nova=n("select id from obres where titol='Obra nova'"); ok(nova and n('select count(*) from obra_agrupacions where obra_id=?',nova)==2, 'obra creada amb dues agrupacions')
h=P(f'r=edita&e=obres&id={nova}', dict(base, **{'agrupacions[]':['']})); ok(n('select count(*) from obra_agrupacions where obra_id=?',nova)==0, 'llevar totes les agrupacions')
h=P('r=edita&e=obres', dict(base, titol='Duplicada', **{'agrupacions[]':['']})); ok('avis error' in h and n("select count(*) from obres where titol='Duplicada'")==0, 'número d arxiu repetit')
h=P('r=edita&e=obres', dict(base, titol='Sense número', numero_arxiu='', **{'agrupacions[]':['']})); h2=P('r=edita&e=obres', dict(base, titol='Sense número 2', numero_arxiu='', **{'agrupacions[]':['']}))
ok(n("select count(*) from obres where titol like 'Sense n%' and numero_arxiu is null")==2, 'dues obres sense número')
h=G('r=edita&e=obres'); ok('value="ARX-0015"' in h, 'el número següent salta les obres sense número')
P(f'r=elimina&e=tipus_obres&id={tp}', {}); ok(n('select count(*) from tipus_obres where id=?',tp)==1, 'no s elimina un tipus en ús')
h=G(f'r=fitxa&e=agrupacions&id={banda}'); ok('r=repertori' in h and 'agrupacio=%d'%banda in h, 'fitxa de l agrupació enllaça amb el repertori')
P(f'r=elimina&e=obres&id={nova}', {}); ok(n('select count(*) from obres where id=?',nova)==0, 'eliminar una obra')
# Importació
full=("Núm. arxiu;Títol de l'obra;Tipus;Compositor/a;Arranjador;Agrupacions;Ubicació física;Format/material;Estat;Digitalitzada;Observacions\n"
      "ARX-0100;Nova importada;Pasdoble;Autor U;;Banda, Coral;Armari Z;Partitura;Completa;sí;\n"
      "ARX-0101;Altra;Fox-trot;Autor D;Arr X;Orquestra inexistent;;;falta flauta;no;Falta la flauta\n"
      ";;Pasdoble;Sense títol;;;;;;;\n"
      "ARX-0100;Repetida;Pasdoble;Autor U;;;;;;;\n"
      "ARX-0001;Paquito el chocolatero;Pasdoble;Gustavo Pascual Falcó;;Coral;Armari NOU;;;;\n").encode('utf-8')
h=multipart('r=importa', dict(accio='puja', tipus='obres', capcalera='1'), ('obres.csv', full))
h=G('r=importa&pas=columnes'); ok(not err(h), 'pas 2 importació obres')
sel=dict(re.findall(r'<select name="col\[(\d+)\]"[^>]*>.*?<option value="([^"]*)" selected', h, re.S))
ok([sel.get(str(i)) for i in range(11)]==['numero_arxiu','titol','tipus_obra','compositor','arranjador','agrupacions','ubicacio','material','estat_obra','digitalitzada','observacions'], 'columnes endevinades: %s'%[sel.get(str(i)) for i in range(11)])
P('r=importa', dict({'accio':'columnes','capcalera':'1'}, **{f'col[{i}]':sel.get(str(i),'') for i in range(11)}))
h=G('r=importa&pas=revisa'); ok(not err(h) and 'Fox-trot' in h and 'inexistent' in h, 'revisió amb tipus nou i agrupació desconeguda')
paq=n("select id from obres where numero_arxiu='ARX-0001'")
h=P('r=importa', {'accio':'importa', 'mateixa[4]':'1'}); h=G('r=importa&pas=fet'); ok(not err(h), 'resultat de la importació')
ok(n("select count(*) from obres where numero_arxiu in ('ARX-0100','ARX-0101')")==2, 'dues obres noves importades')
ok(n("select count(*) from tipus_obres where nom='Fox-trot'")==1, 'tipus nou creat')
ok(n("select estat from obres where numero_arxiu='ARX-0101'")=='incomplet' and n("select digitalitzada from obres where numero_arxiu='ARX-0100'")==1, 'estat i digitalitzada interpretats')
ok(n("select count(*) from obra_agrupacions oa join obres o on o.id=oa.obra_id where o.numero_arxiu='ARX-0100'")==2, 'agrupacions per nom')
ok(n("select ubicacio from obres where id=?",paq)=='Armari NOU' and n('select count(*) from obra_agrupacions where obra_id=?',paq)==3, 'obra existent actualitzada i agrupació afegida')
ok(n("select count(*) from obres where titol='Repetida'")==0, 'repetida al fitxer no s importa')
# Tornar a importar l'exportació no duplica res
exp=G('r=repertori&csv=1', raw=True); antes=n('select count(*) from obres')
multipart('r=importa', dict(accio='puja', tipus='obres', capcalera='1'), ('exp.csv', exp)); h=G('r=importa&pas=columnes')
sel=dict(re.findall(r'<select name="col\[(\d+)\]"[^>]*>.*?<option value="([^"]*)" selected', h, re.S))
P('r=importa', dict({'accio':'columnes','capcalera':'1'}, **{f'col[{i}]':sel.get(str(i),'') for i in range(11)}))
P('r=importa', {'accio':'importa'}); ok(n('select count(*) from obres')==antes, 'reimportar l exportació no duplica')
h=G('r=importa&plantilla=obres', raw=True).decode('utf-8-sig'); ok(h.startswith(('Número d','Número de')), 'plantilla CSV del repertori')
# Mòdul desactivat
P('r=moduls', {'moduls[]':['escola','agrupacions','instruments','uniformes','economia','loteria','caixa','junta','documents','comunicats'], 'avisos[]':[]})
h=G('r=repertori'); ok('HTTP404' in h, 'repertori desactivat')
h=G('r=importa'); ok('value="obres"' not in h, 'importació sense repertori')
h=G(f'r=fitxa&e=agrupacions&id={banda}'); ok('r=repertori' not in h, 'fitxa d agrupació sense repertori')
P('r=moduls', {'moduls[]':['escola','agrupacions','repertori','instruments','uniformes','economia','loteria','caixa','junta','documents','comunicats'], 'avisos[]':[]})
# Base de dades antiga (sense tipus d'obra)
db.execute("delete from config where clau='tipus_obres_inicials'"); db.execute('delete from obra_agrupacions'); db.execute('delete from obres'); db.execute('delete from tipus_obres'); db.execute('pragma user_version = 0'); db.commit()
G('r=inici'); ok(n('select count(*) from tipus_obres')==13, 'tipus d obra creats en actualitzar')
ok(n("select count(*) from sqlite_master where name='idx_mandats_persona'")==0, 'índex sobrant esborrat')
